// =========================================================
// KYDNO KORE - 5 REEL 3D COIN ANIMATION
// Clean circular coin version
// =========================================================

const KYDNO_COIN_ASSETS = {
    heads: "assets/kydno_kore_heads_coin.png",
        tails: "assets/kydno_kore_tails_coin.png"
        };

        const KYDNO_REEL_SIDES = [
            "heads",
                "tails",
                    "heads",
                        "tails",
                            "heads",
                                "tails",
                                    "heads",
                                        "tails"
                                        ];         
     // =========================================================
     // KYDNO KORE - VERTICAL COIN REEL
     // =========================================================
     
     function createKydnoCoin(side) {
     
         const coin = document.createElement("img");
         
             coin.className = "kydno-reel-coin";
             
                 coin.src = KYDNO_COIN_ASSETS[side];
                 
                     coin.alt =
                             side === "heads"
                                         ? "Kydno Kore Heads Coin"
                                                     : "Kydno Kore Tails Coin";
                                                     
                                                         coin.dataset.side = side;
                                                         
                                                             return coin;
                                                             }
                                                             
                                                             
                                                                                                                     
                                                             // =========================================================
                                                             // CREATE ONE VERTICAL REEL
                                                             // =========================================================

                                                             function createKydnoVerticalReel(reelElement) {

                                                                 if (!reelElement) return;

                                                                     reelElement.innerHTML = "";

                                                                         const track =
                                                                                 document.createElement("div");

                                                                                     track.className =
                                                                                             "kydno-vertical-track";


                                                                                                 // Lots of coins so the reel can continuously
                                                                                                     // travel downward without running out.

                                                                                                         for (let i = 0; i < 32; i++) {

                                                                                                                 const side =
                                                                                                                             KYDNO_REEL_SIDES[
                                                                                                                                             i % KYDNO_REEL_SIDES.length
                                                                                                                                                         ];

                                                                                                                                                                 const coin =
                                                                                                                                                                             createKydnoCoin(side);

                                                                                                                                                                                     track.appendChild(coin);
                                                                                                                                                                                         }


                                                                                                                                                                                             reelElement.appendChild(track);


                                                                                                                                                                                                 // Large final result coin.

                                                                                                                                                                                                     const landedCoin =
                                                                                                                                                                                                             document.createElement("img");

                                                                                                                                                                                                                 landedCoin.className =
                                                                                                                                                                                                                         "kydno-landed-coin";

                                                                                                                                                                                                                             landedCoin.alt = "";

                                                                                                                                                                                                                                 reelElement.appendChild(
                                                                                                                                                                                                                                         landedCoin
                                                                                                                                                                                                                                             );
                                                                                                                                                                                                                                             }
                                                                                                                                                                                                     
                                                                                                                                                                                                     
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     // BUILD ALL FIVE REELS
                                                                                                                                                                                                     // =========================================================
                                                                                                                                                                                                     
                                                                                                                                                                                                     const kydnoReelTracks = [];
                                                                                                                                                                                                     
                                                                                                                                                                                                     for (let i = 1; i <= 5; i++) {
                                                                                                                                                                                                     
                                                                                                                                                                                                         const reelElement =
                                                                                                                                                                                                                 document.getElementById(
                                                                                                                                                                                                                             `kydno-reel-${i}`
                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                         createKydnoVerticalReel(
                                                                                                                                                                                                                                                 reelElement
                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                         const track =
                                                                                                                                                                                                                                                                 reelElement?.querySelector(
                                                                                                                                                                                                                                                                             ".kydno-vertical-track"
                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                         if (track) {
                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                 kydnoReelTracks.push(
                                                                                                                                                                                                                                                                                                             track
                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         // SHOW LANDED COIN
                                                                                                                                                                                                                                                                                                                         // =========================================================
                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                         function showKydnoLandedCoin(
                                                                                                                                                                                                                                                                                                                             reelElement,
                                                                                                                                                                                                                                                                                                                                 side
                                                                                                                                                                                                                                                                                                                                 ) {
                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                     if (!reelElement) return;
                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                         const landedCoin =
                                                                                                                                                                                                                                                                                                                                                 reelElement.querySelector(
                                                                                                                                                                                                                                                                                                                                                             ".kydno-landed-coin"
                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                         if (!landedCoin) return;
                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                             landedCoin.src =
                                                                                                                                                                                                                                                                                                                                                                                     KYDNO_COIN_ASSETS[side];
                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                         landedCoin.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                 "show"
                                                                                                                                                                                                                                                                                                                                                                                                     );
                                                                                                                                                                                                                                                                                                                                                                                                     }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
    // =========================================================
    // KYDNO KORE - 5 REEL SPIN TEST
    // =========================================================

    const KYDNO_TEST_RESULTS = [
        "heads",
            "tails",
                "heads",
                    "tails",
                        "heads"
                        ];

       // =========================================================
       // VERTICAL FALLING REEL SPIN
       // =========================================================

       // =========================================================
       // VERTICAL REEL SPIN
       // =========================================================

       // =========================================================
       // CONTINUOUS DOWNWARD REEL SPIN
       // =========================================================

       function spinKydnoReel(
           track,
               reelElement,
                   resultSide,
                       reelNumber,
                           duration
                           ) {

                               if (!track || !reelElement) return;

                                   const coins =
                                           Array.from(
                                                       track.querySelectorAll(".kydno-reel-coin")
                                                               );

                                                                   if (coins.length < 8) return;

                                                                       // Use a coin near the end of the track
                                                                           // as the final result.
                                                                               const targetIndex =
                                                                                       reelNumber === 5 ? 27 : 23;

                                                                                           const targetCoin =
                                                                                                   coins[targetIndex];

                                                                                                       if (!targetCoin) return;

                                                                                                           // Make the target coin the correct result.
                                                                                                               targetCoin.src =
                                                                                                                       KYDNO_COIN_ASSETS[resultSide];

                                                                                                                           targetCoin.dataset.side =
                                                                                                                                   resultSide;

                                                                                                                                       // Measure the actual coin spacing.
                                                                                                                                           const coinHeight =
                                                                                                                                                   targetCoin.getBoundingClientRect().height;

                                                                                                                                                       const firstCoin =
                                                                                                                                                               coins[0];

                                                                                                                                                                   const secondCoin =
                                                                                                                                                                           coins[1];

                                                                                                                                                                               const step =
                                                                                                                                                                                       secondCoin.offsetTop -
                                                                                                                                                                                               firstCoin.offsetTop;

                                                                                                                                                                                                   if (!step) return;

                                                                                                                                                                                                       const reelHeight =
                                                                                                                                                                                                               reelElement.clientHeight;

                                                                                                                                                                                                                   /*
                                                                                                                                                                                                                           The reel visually moves DOWNWARD.

                                                                                                                                                                                                                                   We begin with coin #2 near the center.
                                                                                                                                                                                                                                           We finish with the target coin near
                                                                                                                                                                                                                                                   the center.

                                                                                                                                                                                                                                                           Because the target is much farther down
                                                                                                                                                                                                                                                                   the track, the entire stack travels
                                                                                                                                                                                                                                                                           through the window.
                                                                                                                                                                                                                                                                               */

                                                                                                                                                                                                                                                                                   const startIndex = 2;

                                                                                                                                                                                                                                                                                       const startOffset =
                                                                                                                                                                                                                                                                                               (reelHeight / 2) -
                                                                                                                                                                                                                                                                                                       (startIndex * step) -
                                                                                                                                                                                                                                                                                                               (coinHeight / 2);

                                                                                                                                                                                                                                                                                                                   const finalOffset =
                                                                                                                                                                                                                                                                                                                           (reelHeight / 2) -
                                                                                                                                                                                                                                                                                                                                   (targetIndex * step) -
                                                                                                                                                                                                                                                                                                                                           (coinHeight / 2);

                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                       Reverse the direction of the physical
                                                                                                                                                                                                                                                                                                                                                               track movement so the coins themselves
                                                                                                                                                                                                                                                                                                                                                                       travel DOWN through the white window.
                                                                                                                                                                                                                                                                                                                                                                           */

                                                                                                                                                                                                                                                                                                                                                                               const startY =
                                                                                                                                                                                                                                                                                                                                                                                   startOffset;

                                                                                                                                                                                                                                                                                                                                                                                   const endY =
                                                                                                                                                                                                                                                                                                                                                                                       finalOffset;

                                                                                                                                                                                                                                                                                                                                                                                                       const startTime =
                                                                                                                                                                                                                                                                                                                                                                                                               performance.now();

                                                                                                                                                                                                                                                                                                                                                                                                                   track.style.transition = "none";

                                                                                                                                                                                                                                                                                                                                                                                                                       track.style.transform =
                                                                                                                                                                                                                                                                                                                                                                                                                               `translate(-50%, ${startY}px)`;

                                                                                                                                                                                                                                                                                                                                                                                                                                   function animateReel(currentTime) {

                                                                                                                                                                                                                                                                                                                                                                                                                                           const elapsed =
                                                                                                                                                                                                                                                                                                                                                                                                                                                       currentTime - startTime;

                                                                                                                                                                                                                                                                                                                                                                                                                                                               let progress =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           elapsed / duration;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (progress > 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               progress = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           Normal reels slow down smoothly.

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       Reel 5 gets a much longer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   heavier slowdown.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const eased =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               1 - Math.pow(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               1 - progress,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               reelNumber === 5 ? 6 : 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const currentY =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               startY +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           endY -
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           startY
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ) * eased;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               track.style.transform =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           `translate(-50%, ${currentY}px)`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (progress < 1) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               animateReel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Hide the moving reel.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       coins.forEach((coin) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       coin.style.opacity = "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Show the large final result.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       showKydnoLandedCoin(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       resultSide
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Reel 5 gets the final impact.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (reelNumber === 5) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       reelElement.classList.add(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           "kydno-reel-landed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               reelElement.classList.remove(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       "kydno-reel-landed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }, 450);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       requestAnimationFrame(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               animateReel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                 
                                                                
  // =========================================================
  // RUN THE 5 REEL SPIN TEST
  // =========================================================

  function runKydnoSpinTest() {

      // Reset the reels first
         kydnoReelTracks.forEach((track) => {

                track.style.transition = "none";

                    track.style.transform =
                            "translate(-50%, 0px)";

                                track
                                        .querySelectorAll(".kydno-reel-coin")
                                                .forEach((coin) => {
                                                            coin.style.opacity = "1";
                                                                    });
                                                                    });
         

                                                                              // Hide previous result coins
                                                                                  kydnoReelTracks.forEach((track, index) => {

                                                                                          const reelElement =
                                                                                                      document.getElementById(
                                                                                                                      `kydno-reel-${index + 1}`
                                                                                                                                  );

                                                                                                                                          const landedCoin =
                                                                                                                                                      reelElement?.querySelector(
                                                                                                                                                                      ".kydno-landed-coin"
                                                                                                                                                                                  );

                                                                                                                                                                                          if (landedCoin) {
                                                                                                                                                                                                      landedCoin.classList.remove("show");
                                                                                                                                                                                                                  landedCoin.removeAttribute("src");
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                  // Wait for the reset to happen
                                                                                                                                                                                                                                      requestAnimationFrame(() => {

                                                                                                                                                                                                                                              requestAnimationFrame(() => {

                                                                                                                                                                                                                                                          // Reel 1 → 2 → 3 → 4
                                                                                                                                                                                                                                                                      // Reel 5 gets the dramatic slowdown

                                                                                                                                                                                                                                                                                  const durations = [
                                                                                                                                                                                                                                                                                                  1600,
                                                                                                                                                                                                                                                                                                                  2100,
                                                                                                                                                                                                                                                                                                                                  2600,
                                                                                                                                                                                                                                                                                                                                                  3100,
                                                                                                                                                                                                                                                                                                                                                                  5000
                                                                                                                                                                                                                                                                                                                                                                              ];

                                                                                                                                                                                                                                                                                                                                                                                          kydnoReelTracks.forEach(
                                                                                                                                                                                                                                                                                                                                                                                                          (track, index) => {

                                                                                                                                                                                                                                                                                                                                                                                                                              const reelNumber =
                                                                                                                                                                                                                                                                                                                                                                                                                                                      index + 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const reelElement =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `kydno-reel-${reelNumber}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          spinKydnoReel(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  track,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelElement,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  KYDNO_TEST_RESULTS[index],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          reelNumber,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  durations[index]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Automatically start the test
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setTimeout(() => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  runKydnoSpinTest();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }, 500);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Allows us to restart the test later
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  window.runKydnoSpinTest =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      runKydnoSpinTest;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
